# -*- coding: utf-8 -*-
from transformers import LongformerForSequenceClassification, LongformerTokenizer
import torch

# Check if GPU is available
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

# Path to your model directory
model_path = "/sise/home/avramit/hebnli/HEBSNLI_model/LCHAIM+HEBSNLI"

# Load the tokenizer and model
tokenizer = LongformerTokenizer.from_pretrained(model_path)
model = LongformerForSequenceClassification.from_pretrained(model_path)

# Move model to GPU
model.to(device)

# Set the model to evaluation mode
model.eval()

# Example input: Natural Language Inference (NLI) task
# hypothesis = """עיריית תל אביב אישרה תקן חניה חדש לפיו במרכז העיר יוקצה לכל היותר מקום חניה אחד לכל שתי דירות חדשות. התקן החדש יביא לצמצום במספר מקומות החניה באזורים אלו, מה שצפוי להשפיע על מחירי החניה הקיימים. כבר היום, הביקוש הגבוה לחניה בתל אביב ניכר במחירי השכרה ומכירה גבוהים. מומחים מעריכים כי צמצום מקומות החניה בפרויקטים חדשים יוביל לעלייה משמעותית במחירי החניה הקיימים, במיוחד במרכז העיר. ההיגיון מאחורי המהלך הוא לעודד שימוש בתחבורה ציבורית, אך ישנם חששות בנוגע ליישומיותו בטווח הקצר והבינוני. עיריית תל אביב מקדמת פעולות שונות בתחום החניה, ביניהן הגבלת תווי חניה, תמחור דיפרנציאלי, פתרונות חנה וסע והרחבת אפשרויות התחבורה הציבורית. מטרת המהלך היא לצמצם את השימוש ברכב פרטי ולהפוך את תל אביב לעיר ידידותית יותר להולכי רגל ורוכבי אופניים. מומחים מעריכים שמחירי החניה ימשיכו לעלות עד שתשתיות התחבורה הציבורית יהיו תחליף ראוי לרכב הפרטי. יש פער משמעותי בין מחירי חניה במקומות שונים בתל אביב, כאשר חניות תת קרקעיות ומקורות יקרות יותר מחניות פתוחות. על פי נתוני אתר יד2, מחירי חניה למכירה בתל אביב נעים בין 140 אלף שקל ל-550 אלף שקל, תלוי באזור. מחירי השכרת חניה בתל אביב נעים בין 350 שקל לחודש ל-1,250 שקל לחודש, תלוי במיקום. המצב מחייב פתרונות תחבורה יצירתיים, כגון שבילי אופניים, עבודה מהבית ועידוד תחבורה שיתופית."""
# premise = """אין חניה תקן חדש במרכז ת\"א: חניה אחת לכל שתי דירות. בדיקה באתר יד2 משקפת את הביקוש והמצוקה גם בתל אביב כמו ניו יורק, לונדון או סינגפור החניה הופכת למצרך מבוקש ויקר כמעט כמו בית. מחיר מקום חניה בלב תל אביב שווה היום לדירת 3 חדרים בבאר שבע. במנהטן נמכרה כבר חניה במיליון דולר. ובישראל? לאט לאט אנחנו בדרך לשם. לפני כשבועיים הוועדה המקומית לתכנון ובנייה בעיריית תל אביב אישרה תקן חניה עדכני לתוכניות בניין העיר העתידיות. במרכז העיר תקן החניה המקסימלי יעמוד מעתה על 0.5 חניות לכל יחידה. כלומר, מקום חניה אחד בלבד לכל שתי דירות. בצפון העיר ובדרומה יעמוד התקן המקסימלי על 0.8. המשמעות היא שכל דירה חדשה שנייה שתיבנה במרכז העיר תימכר ללא חניה מוצמדת. כיצד זה ישפיע על מחירי החניות? כבר היום חניה בתל אביב היא מוצר נדיר גם למי שגר בעיר וגם למי שמבקר או עובד בה. על פי נתוני אתר יד 2, מחירי החניה בתל אביב משקפים את הביקושים הגבוהים מצד תושבים ומבקרים. מקומות חניה למכירה נעים בין 140 ל-550 אלף שקל, ומחירי ההשכרה נעים בין 350 שקל לחודש (4,200 שקל לשנה) ועד 1,250 שקל בחודש (15,000 שקל לשנה), תלוי בשכונה. החניות מהוות עסק מניב לכל דבר, עם תשואה ממוצעת של 0.3%-0.4% מהשכרה ותמורה שנעה בין 6% ל-13% משווי הדירה בעת מכירת מקום החניה. כאשר בוחנים את המחירים לפי שכונות, בלב העיר צפון (רחובות אחד העם / בלפור) מחיר חניה לרכישה הוא היקר ביותר ומגיע לכ-550 אלף שקל. ברחובות אחרים באותה שכונה המחיר עומד על 500 אלף שקל. מחירי החניה בשכונת נווה צדק עומדים על 450 אלף שקל והתמורה מהמכירה היא 9% מערך הדירה. בשכונת כרם התימנים המחיר דומה והתמורה 10%. ברמת אביב ג' מחירי החניות 250-400 אלף שקל והתמורה נעה בין 7% ל-10%. עלות חניה בתל אביב עומדת כיום בממוצע על כ-35,000 שקל למ\"ר, הרבה יותר מהמחיר למ\"ר בדירות במרבית הערים בארץ. יותר רכבים, פחות חניה לדברי חיים מסילתי יו\"ר לשכת שמאי המקרקעין, ״בשנים האחרונות ישנה מגמה לפיה מצד אחד יש פחות מקומות חניה בתל אביב, בעיקר במרכזה, ומצד שני יש יותר מכוניות. ישנם אזורים המאופיינים במשפחות צעירות, בהן לכל משפחה יותר מרכב אחד. ככל שהמצוקה מתגברת כך גם הביקוש עולה ואיתו המחיר. בצפון ובדרום תל אביב מצוקת החניה פחות מורגשת, ולכן המחירים פחות יקרים מאשר במרכז העיר\". מסילתי מעריך כי מצוקת החניה תגבר משמעותית לאור הפחתת תקני החניה בפרויקטים חדשים למגורים ומדגיש כי המספרים שצוינו מהווים גבול מקסימלי, כלומר שניתן אף לקבוע תקן נמוך יותר. ב-2018 צומצמו מקומות החניה בפרויקטים לתעסוקה, מסחר, מוסדות חינוך, תרבות ופנאי. ככל שהפרויקט קרוב יותר למוקדי תחבורה ציבורית כך התקן נמוך יותר. \"מחירי החניות עשוים לעלות בעשרות אחוזים, זאת עד להקמת תשתית תחבורתית ציבורית הולמת, שתהווה תחליף ראוי לכלי הרכב הפרטיים\", אומר מסילתי. פרמטר נוסף שמשפיע על המחיר הוא סוג החניה: חניות פתוחות, מקורות ותת קרקעיות, שהן הרבה יותר נוחות ומתומחרות במחיר גבוה. ישנה שונות גם בחניות בתוך מרתפי החניה, למשל על פי הסמיכות למעלית וליציאה. הפער בין חניה איכותית בתוך חניון תת קרקעי לחניה במיקום פחות אטרקטיבי מחוצה לו יכול להגיע ל-10% ואף יותר. \"מחירי החניות צפויים להמשיך לעלות בשנים הקרובות\", מעריך מסילתי, \"לפחות עד שהתשתית התחבורתית המדוברת, כגון הרכבת הקלה והמטרו, תיתן מענה חלופי לציבור ותעודד אנשים לוותר על השימוש ברכבים פרטיים\". גישה בעייתית בטווח הקצר לדברי עו\"ד ענת בירן מומחית לתכנון ולבנייה, הנטייה כיום היא להקטין את תקני החניה בתחום המגורים והמשרדים כאחד. \"הרציונל הוא שהודות לנגישות לתחבורה ציבורית לא יהיה צורך ברכב פרטי. מדובר בגישה בעייתית בטווח הקצר והבינוני, שכן עדיין לא ברור האם ומתי המטרו וקווי הרכבת הקלה העתידיים יחלו לפעול\". משמעות הפחתת תקן החניה בתל אביב, לדבריה, היא שרבים מהתושבים לא יוכלו להחזיק מכונית. \"זהו מצב בעייתי לתושבים במציאות שבה אין תחבורה ציבורית טובה, וכן ליזמים שעמלים על תוכניות כבר שנים, ולפתע צריכים לשנות אותן בהתאם לתקני החניה החדשים, ולבצע אומדנים כלכליים בהתאם. \"יש רשויות כמו הרצליה וגבעתיים שדורשות תקן חניה גבוה, חניות תת קרקעיות המחייבות ירידה למספר קומות מרתף וכיו\"ב. חוסר ההלימה בין צמצום מקומות החניה באזורי התעסוקה ודרישה מוגברת למקומות חניה בערים שמחוץ לתל אביב מעוררת בעיה אמיתית למשתמשי הרכב הפרטי, שאין להם חניה בהישג יד במקומות עבודתם. \"כל אלה, לצד האיטיות וחוסר הוודאות בקשר למימוש תוכניות התחבורה הציבורית, מחייבים תכנון שכונות המאפשרות פתרונות תחבורה יצירתיים, נוחים ובטוחים להולכי רגל לצד שבילי אופניים, ופתרונות חדשניים של עבודה מהבית או בסמוך לבית, באופן שיצמצם את בעיות התחבורה\". לחשב מסלול מחדש מיטל להבי סגנית ראש עיריית תל-אביב-יפו ומחזיקת תיק התחבורה מסבירה שההצעה להגדרת תקן חניה מופחת בעיר מתאימה למדיניות של העירייה \"להפוך את פירמידת התנועה, לשים את הולכי הרגל בראש סדר העדיפויות ולצמצם את השימוש ברכב פרטי בעיר\". \"מדובר בהצעה שנגזרת מהמציאות הפקוקה שאנו חיים בה ושעוד עתידה להתפוקק עוד יותר עם הכניסה לביצוע קווי רכבת קלה, נתיבי תחבורה נוספים ושבילי אופניים, שיצמצמו את קיבולת הדרכים בעיר ובכניסות אליה\", אומרת להבי. \"זאת, לצד הגידול בצפיפות העירונית, מחייבים אותנו לחשב מסלול מחדש ולקבל החלטות לא פשוטות בנוגע לחלוקת המרחב העירוני״. להבי מפרטת פעולות שונות שהעירייה מקדמת בתחום החניה, ביניהן הגבלת החלוקה של תווי חניה, תמחור דיפרנציאלי של החניה ברחובות, הסדרת מנגנון לחניה קצרת טווח ברחובות מסחריים, פתרונות אלטרנטיביים לחניוני חנה וסע במבואות העיר, הרחבת המענים להתניידות שיתופית, הסדרה של כללי התניידות בכלים האישיים ופיתוח תשתיות לרכיבה בטוחה, ביצוע נתיבי תחבורה ציבורית נוספים והעלאת רמת השירות לנוסעים, עידוד פריסת מוניות השירות והמשך הפעלה של מיזמים כמו נעים בסופ\"ש, שמטרתם לספק מענים להתניידות 24/7\n\n"""

hypothesis = "עיריית תל אביב מקדמת פעולות לצמצום השימוש ברכב פרטי על ידי צמצום מקומות חניה."
premise = """עיריית תל אביב מקדמת תקן החדש יביא לצמצום במספר מקומות החניה באזורים מסוימים, מה שצפוי להשפיע על מחירי החניה הקיימים לרכבים פרטיים ואפילו כבר היום, הביקוש הגבוה לחניה של רכבים פרטיים בתל אביב ניכר במחירי השכרה ומכירה גבוהים לעומת התחבורה הציבורית"""
# premise = "הזרוע הימנית של האיש נשברה והתפתלה לחלוטין"
# hypothesis = "איש נפצע"
print(hypothesis)
print(premise)
# Tokenize the inputs (Longformer supports long sequences)
inputs = tokenizer(
    premise,
    hypothesis,
    return_tensors="pt",
    padding="max_length",
    truncation=True,
    max_length=4096
)

# Move inputs to GPU
inputs = {key: value.to(device) for key, value in inputs.items()}

# Run the model and get logits
with torch.no_grad():
    outputs = model(**inputs)
    logits = outputs.logits

# Get the predicted label
id2label = {0: "Entailment", 1: "Neutral", 2: "Contradiction"}
predicted_label = torch.argmax(logits, dim=1).item()

# Print the result
print(f"Predicted label: {id2label[predicted_label]}")
